#!/usr/bin/env bash
# Removes every entry from an updates index whose GitHub release v<version> no longer exists (deleted release: the
# download URLs would 404 and `release-add -keep` would keep the entry forever). Any channel, hub and player.
#   prune-index-missing-releases.sh <uzume-sign> <updates-index.json>
# Only a real "release not found" removes an entry; any other gh error (network, rate limit, 5xx) after 3 attempts stops
# the script, so a flaky API never shrinks the index. Legacy companions (X.Y.Z-legacy) are regenerated by uzume-sign.
# Needs gh (GH_TOKEN, GH_REPO) and jq. Called by update-index.sh before the index is changed (release.yml, promote.yml).
set -euo pipefail

[ $# -eq 2 ] || { echo "usage: $0 <uzume-sign> <updates-index.json>" >&2; exit 2; }
sign="$1"
index="$2"
[ -f "$index" ] || { echo "::error::index file not found: $index" >&2; exit 1; }
err="$(mktemp)"
trap 'rm -f "$err"' EXIT

# Exit 0 = release exists, 44 = release not found, 1 = any other error after 3 attempts.
release_exists() {
  local tag="$1" i
  for i in 1 2 3; do
    if gh release view "$tag" --json tagName >/dev/null 2>"$err"; then
      return 0
    fi
    if grep -qi 'release not found' "$err"; then
      return 44
    fi
    echo "::warning::gh release view $tag failed (attempt $i/3): $(head -c 300 "$err")" >&2
    [ "$i" -eq 3 ] || sleep $((i * 5))
  done
  return 1
}

# Snapshot the entries first: the index file is rewritten while we loop.
entries="$(jq -r '.releases[] | select(.version | endswith("-legacy") | not) | "\(.product) \(.channel) \(.version)"' "$index")"
while read -r product channel version; do
  [ -n "${version:-}" ] || continue
  rc=0
  release_exists "v$version" || rc=$?
  case "$rc" in
    0) ;;
    44)
      echo "Release v$version no longer exists; removing $product $channel $version from the index"
      "$sign" release-remove -index "$index" -product "$product" -channel "$channel" -version "$version"
      ;;
    *) echo "::error title=Updates index::could not check release v$version (not a 'release not found' error); refusing to continue" >&2; exit 1 ;;
  esac
done <<<"$entries"
